            if (request.TheftPolicyForTest is { } theftPolicy)
                SolverController.SetTheftPolicyForTesting(combatState, theftPolicy);
            SolverController.SetStopFullAutoOnCombatEnd(false, persist: false);
            SolverController.SetStopFullAutoOnDeathTurn(
                request.ExpectedFullAutoPausedAtDeathTurn
                    || request.ExpectedFullAutoPausedAtLiveRisk,
                persist: false);
            SolverController.SetStopFullAutoOnWorseRecalculation(
                request.EnableStopOnWorseRecalculationForTest
                    || request.ExpectedFullAutoPausedAfterWorseRecalculation
                    || request.ExpectedFullAutoPausedAtLiveRisk,
                persist: false);
            runner._protocolHost.EnableAutomaticTurnSearch();
            bool manualMemoryReleaseContract = request.ScenarioId == "MANUAL-MEMORY-RELEASE-AUTO-CONTRACT";
            if (request.HoldAfterInitialSearch
                || request.ManualEndTurnAfterInitialSearch
                || request.SingleStepAfterInitialSearch
                || request.StopAfterInitialSolverResultAssertion
                || manualMemoryReleaseContract)
                SolverController.RequestSearch(runner._host, combatState, SearchReason.Manual);
            else
                SolverController.SetFullAuto(runner._host, combatState, enabled: true);

            if (runner.HasInitialSolverExpectation()
                || request.StopAfterInitialSolverResultAssertion
                || manualMemoryReleaseContract)
                await runner.AssertInitialSolverResultAsync(startedTurn);

            if (manualMemoryReleaseContract)
                await runner.RunManualMemoryReleaseAutoContractAsync(combatState);

            if (request.StopAfterInitialSolverResultAssertion)
            {
                if (request.ScenarioId == "ADAPTED-ONPLAY-INTEGRATION-STALE")
                    runner.AssertAdaptedOnPlayCachedRoute();
                return Observation(combatEnded: false);
            }

            if (request.HoldAfterInitialSearch)
            {
                if (!runner.HasInitialSolverExpectation())
                    await runner.AssertInitialSolverResultAsync(startedTurn);
                await Task.Delay(2000);
                await SearchGcPolicy.ReclaimIfPendingAsync(
                    "unattended_hold",
                    forceCollection: true);
                return Observation(combatEnded: false, initialSearchHeld: true);
            }

            if (request.SingleStepAfterInitialSearch)
            {
                if (!runner.HasInitialSolverExpectation())
                    await runner.AssertInitialSolverResultAsync(startedTurn);
                runner.SetStage("single_step_next_turn_choice");
                SolverController.RequestDeploy(runner._host, combatState);
                int expectedTurn = startedTurn + 1;
                while (CombatManager.Instance.IsInProgress && !CombatManager.Instance.IsOverOrEnding)
                {
                    bool waitingForPlayer = player.PlayerCombatState is
                        {
                            TurnNumber: var turn,
                            Phase: PlayerTurnPhase.Start,
                        }
                        && turn == expectedTurn
                        && NPlayerHand.Instance?.IsInCardSelection == true;
                    if (waitingForPlayer)
                    {
                        if (SolverController.FullAutoEnabled)
                            throw new InvalidOperationException("单步执行进入下一回合选牌页时仍处于全自动模式。");
                        bool solverSelected = NativeChoiceRuntime.TraceSnapshotForTesting.Any(trace =>
                            trace.Owner == $"turn_setup:{expectedTurn}"
                            && trace.Stage == "Selected");
                        if (solverSelected)
                            throw new InvalidOperationException("单步执行越过边界并替玩家完成了下一回合选牌。");
                        if (SolverOverlay.CurrentSnapshotTurnForTesting != expectedTurn)
                        {
                            throw new InvalidOperationException(
                                $"下一回合选牌页已显示，但路线 UI 仍停在第 " +
                                $"{SolverOverlay.CurrentSnapshotTurnForTesting?.ToString() ?? "-"} 回合；" +
                                $"预期第 {expectedTurn} 回合。");
                        }
                        runner._completedChecks.Add(
                            $"SingleStepBoundary:Turn={expectedTurn}:Surface=Hand:Selected=0:UiTurn={expectedTurn}");
                        Entry.Logger.Info(
                            $"[CombatSolver/Test] SINGLE_STEP_BOUNDARY turn={expectedTurn} " +
                            $"surface=Hand waiting_for_player=true solver_selected=false ui_turn={expectedTurn}");
                        if (request.ScenarioId is "TOASTY-QOL-MANUAL-SAME" or "TOASTY-QOL-MANUAL-DIFFERENT"
                            or "TOASTY-QOL-FROZEN-SAME" or "TOASTY-QOL-FROZEN-DIFFERENT")
                        {
                            if (request.ScenarioId == "TOASTY-QOL-MANUAL-SAME")
                            {
                                SolverResult source = SolverController.LastCompletedResultForTesting
                                    ?? throw new InvalidOperationException("原生选牌预览缺少首轮路线。");
                                BattleDamageSnapshot observed = new(7, 0, 0, [], 2);
                                SolverOverlaySnapshot pending = SolverOverlaySnapshot.CapturePendingTurnSetup(
                                    source, observed, expectedTurn, unexpectedReplan: false);
                                int futureLoss = source.HpLostByTurn
                                    .Where(item => item.Key >= expectedTurn).Sum(item => item.Value);
                                int futureRecovery = source.HpRecoveredByTurn
                                    .Where(item => item.Key >= expectedTurn).Sum(item => item.Value);
                                if (pending.ProjectedBattleHpLost != 7 + futureLoss
                                    || pending.RouteHpRecovered != 2 + futureRecovery
                                    || !pending.HpOutcomeText.Contains($"已 7    预计 {7 + futureLoss} HP",
                                        StringComparison.Ordinal)
                                    || !pending.DetailsText.Contains("本局已发生 7", StringComparison.Ordinal))
                                {
                                    throw new InvalidOperationException("原生选牌预览丢失本场已受伤或已回血前缀。");
                                }
                                runner._completedChecks.Add("PendingTurnSetup:ObservedLoss=7:ObservedRecovery=2");
                            }
                            bool different = request.ScenarioId.EndsWith("DIFFERENT", StringComparison.Ordinal);
                            bool frozen = request.ScenarioId.Contains("FROZEN", StringComparison.Ordinal);
                            int searchesBeforeChoice = SolverController.SearchesStartedForTesting;
                            if (frozen)
                            {
                                SolverController.SetRouteFrozen(runner._host, combatState, true);
                                if (!SolverController.RouteFrozen || SolverController.FullAutoEnabled)
                                    throw new InvalidOperationException("选牌页冻结未停止自动接管。");
                            }
                            await PlayerTurnSetupCoordinator.SelectPlannedOrDifferentChoiceForTesting(
                                runner._host, different);
                            while (PlayerTurnSetupCoordinator.IsManaging(combatState)
                                   || player.PlayerCombatState?.Phase != PlayerTurnPhase.Play
                                   || (!different && !SolverController.CanExecuteCurrentTurn)
                                   || (different && !frozen && SolverController.UnexpectedReplanCountForTesting == 0)
                                   || SolverController.IsSearching)
                            {
                                runner.EnsureWithinDeadline();
                                await runner.NextFrameAsync();
                            }
                            if (frozen)
                            {
                                if (!SolverController.RouteFrozen
                                    || SolverController.SearchesStartedForTesting != searchesBeforeChoice
                                    || SolverController.CanExecuteCurrentTurn == different)
                                    throw new InvalidOperationException("冻结路线的精确续用/失配状态不正确。");
                                if (different)
                                {
                                    SolverController.RequestDeploy(runner._host, combatState);
                                    if (SolverController.SearchesStartedForTesting != searchesBeforeChoice)
                                        throw new InvalidOperationException("过期冻结路线触发了搜索或执行。");
                                    SolverController.RequestSearch(runner._host, combatState, SearchReason.Manual);
                                    while (SolverController.IsSearching
                                           || SolverController.SearchesStartedForTesting == searchesBeforeChoice
                                           || !SolverController.CanExecuteCurrentTurn)
                                    {
                                        runner.EnsureWithinDeadline();
                                        await runner.NextFrameAsync();
                                    }
                                    if (SolverController.RouteFrozen || !SolverController.CanExecuteCurrentTurn)
                                        throw new InvalidOperationException("手动重新计算未解除冻结并恢复可执行路线。");
                                }
                            }
                            else if (different)
                            {
                                if (SolverController.UnexpectedReplanCountForTesting == 0
                                    || SolverController.LastReusedTurnForTesting == expectedTurn
                                    || SolverController.SearchesStartedForTesting <= searchesBeforeChoice)
                                    throw new InvalidOperationException("不同的原生删牌未触发严格失配重算。");
                            }
                            else if (SolverController.SearchesStartedForTesting != searchesBeforeChoice
                                     || SolverController.UnexpectedReplanCountForTesting != 0)
                                throw new InvalidOperationException("按计划手动删牌产生了重复搜索。");
                            runner._completedChecks.Add($"ToastyManualChoice:Turn={expectedTurn}:" +
                                (frozen
                                    ? different ? "FrozenMismatch=ReferenceOnly:ManualRecalculation=true"
                                        : "FrozenExactReused=true:SearchesAdded=0"
                                    : different ? "MismatchReplanned=true" : "ExactReused=true:SearchesAdded=0"));
                            return Observation(combatEnded: false);
                        }
                        if (request.SingleStepResumeModeForTest is not { } resumeMode)
                            return Observation(combatEnded: false);

                        if (request.ScenarioId == "TOASTY-QOL-SINGLE-STEP-EXECUTE")
                        {
                            while (!PlayerTurnSetupCoordinator.ReplaySurfacePreparedForTesting)
                            {
                                runner.EnsureWithinDeadline();
                                await runner.NextFrameAsync();
                            }
                            if (!SolverController.CanExecuteCurrentTurn
                                || SolverOverlay.ExecuteButtonDisabledForTesting)
                            {
                                throw new InvalidOperationException(
                                    "回合开始选牌页已有可接管路线，但‘执行本回合’按钮仍不可用：" +
                                    PlayerTurnSetupCoordinator.DescribeControlsForTesting());
                            }
                        }

                        if (request.ScenarioId == "TOASTY-QOL-AUTO-OFF-FULLAUTO")
                        {
                            SolverController.SetAutomaticCalculationEnabled(false, persist: true);
                            if (SolverController.AutomaticCalculationEnabled)
                                throw new InvalidOperationException("自动计算未关闭。");
                        }

                        long previousDeploymentStartedAt =
                            SolverController.LastDeployedActionStartedAtMillisecondsForTesting;
                        int searchesBeforeTakeover = SolverController.SearchesStartedForTesting;
                        if (request.ScenarioId == "TOASTY-QOL-SINGLE-STEP-EXECUTE")
                            SolverOverlay.PressExecuteButtonForTesting();
                        else if (resumeMode == SingleStepResumeMode.ExecuteCurrentTurn)
                            SolverController.RequestDeploy(runner._host, combatState);
                        else
                            SolverController.SetFullAuto(runner._host, combatState, enabled: true);

                        while (SolverController.LastDeployedActionStartedAtMillisecondsForTesting
                               <= previousDeploymentStartedAt)
                        {
                            runner.EnsureWithinDeadline();
                            await runner.NextFrameAsync();
                        }

                        NativeChoiceTrace selectedTrace = NativeChoiceRuntime.TraceSnapshotForTesting
                            .Where(trace => trace.Owner == $"turn_setup:{expectedTurn}"
                                && trace.Stage == "Selected")
                            .OrderByDescending(trace => trace.Order)
                            .FirstOrDefault()
                            ?? throw new InvalidOperationException(
                                "接管单步回合开始页面后没有完成计划选牌。");
                        long deploymentStartedAt =
                            SolverController.LastDeployedActionStartedAtMillisecondsForTesting;
                        long actualDelay = deploymentStartedAt - selectedTrace.OccurredAtMilliseconds;
                        if (request.ExpectedTurnSetupToDeploymentDelayMillisecondsAtLeast
                            is { } minimumDelay
                            && actualDelay < minimumDelay)
                        {
                            throw new InvalidOperationException(
                                $"回合开始选牌到下一张牌只间隔 {actualDelay} ms，低于预期 {minimumDelay} ms。");
                        }
                        if (SolverController.LastCompletedResultForTesting is not
                            {
                                WasReused: true,
                                StartTurnNumber: var reusedTurn,
                            }
                            || reusedTurn != expectedTurn)
                        {
                            throw new InvalidOperationException(
                                $"接管第 {expectedTurn} 回合选牌后没有复用既有路线。");
                        }
                        if (SolverController.UnexpectedReplanCountForTesting != 0)
                            throw new InvalidOperationException("接管单步选牌页后发生了计划外重算。");
                        if (request.ScenarioId == "TOASTY-QOL-SINGLE-STEP-EXECUTE"
                            && (SolverController.SearchesStartedForTesting != searchesBeforeTakeover
                                || SolverController.FullAutoEnabled))
                        {
                            throw new InvalidOperationException(
                                "执行本回合的原生选牌接管触发了额外搜索或开启全自动。");
                        }
                        if (request.ScenarioId == "TOASTY-QOL-AUTO-OFF-FULLAUTO"
                            && (!SolverController.FullAutoEnabled
                                || SolverController.AutomaticCalculationEnabled))
                            throw new InvalidOperationException("关闭自动计算后全自动续执行状态错误。");
                        runner._completedChecks.Add(
                            $"SingleStepTakeover:Mode={resumeMode}:Turn={expectedTurn}:" +
                            $"DelayMs={actualDelay}:Reused=true:UnexpectedReplans=0");
                        return Observation(combatEnded: false);
                    }
                    runner.EnsureWithinDeadline();
                    await runner.NextFrameAsync();
                }
                throw new InvalidOperationException("单步执行在下一回合原生选牌页出现前结束了战斗。");
            }

            if (request.ManualEndTurnAfterInitialSearch)
            {
                if (!runner.HasInitialSolverExpectation())
                    await runner.AssertInitialSolverResultAsync(startedTurn);
                runner.SetStage("manual_end_turn");
                int manualTurn = player.PlayerCombatState?.TurnNumber
                    ?? throw new InvalidOperationException("手操偏离测试没有玩家回合状态。");
                CombatManager.Instance.OnEndedTurnLocally();
                RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue(
                    new EndPlayerTurnAction(player, manualTurn));
                await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
                if (request.EnableFullAutoAfterManualEndTurn)
                {
                    CombatState resumedState = await runner.WaitForPlayableCombatAsync();
                    SolverController.SetFullAuto(runner._host, resumedState, enabled: true);
                }
            }

            runner.SetStage("wait_combat_end");
            bool expectedReuseObserved = !request.ExpectedReusedTurn.HasValue;
            bool ObserveExpectedReuse()
            {
                SolverResult? latestResult = SolverController.LastCompletedResultForTesting;
                int? observedReusedTurn = SolverController.LastReusedTurnForTesting
                    ?? (latestResult?.WasReused == true
                        ? latestResult.StartTurnNumber
                        : null);
                if (observedReusedTurn != request.ExpectedReusedTurn)
                    return false;
                int observedProjectedBattleHpLost =
                    SolverController.LastReusedProjectedBattleHpLostForTesting
                    ?? latestResult?.ProjectedBattleHpLost
                    ?? throw new InvalidOperationException("复用测试没有记录整场预计战损。");
                if (request.ExpectedReusedProjectedBattleHpLost is { } expectedReusedLoss
                    && observedProjectedBattleHpLost != expectedReusedLoss)
                {
                    throw new InvalidOperationException(
                        $"第 {observedReusedTurn} 回合复用路线预计整场掉血 " +
                        $"{observedProjectedBattleHpLost}，预期为 {expectedReusedLoss}。");
                }
                return true;
            }
            bool stoppedAfterExpectedReuse = false;
            bool stoppedAfterExpectedPower = false;
            bool stoppedAfterDeathTurnPause = false;
            bool stoppedAfterWorseRecalculationPause = false;
            bool stoppedAfterLiveRiskPause = false;
            bool stoppedAfterManualDivergence = false;
            bool stoppedAfterNoGcRollover = false;
            bool stoppedAfterExpectedUnexpectedReplan = false;
            int maximumUnexpectedReplans = 0;
            while (CombatManager.Instance.IsInProgress && !CombatManager.Instance.IsOverOrEnding)
            {
                expectedCardPlayed |= runner.WasExpectedCardPlayed();
                expectedPotionUsed |= runner.WasExpectedPotionUsed();
                expectedPlayerPowerObserved |= runner.HasExpectedPlayerPower(player);
                maximumUnexpectedReplans = Math.Max(
                    maximumUnexpectedReplans,
                    SolverController.UnexpectedReplanCountForTesting);
                if (request.StopAfterExpectedUnexpectedReplan
                    && request.ExpectedUnexpectedReplansAtLeast is { } minimumUnexpectedReplans
                    && maximumUnexpectedReplans >= minimumUnexpectedReplans)
                {
                    if (request.ExpectedUnexpectedReplanWarning
                        && !SolverOverlay.UnexpectedReplanWarningVisibleForTesting)
                    {
                        throw new InvalidOperationException("已发生计划外重算，但标题右侧没有显示反馈告警。");
                    }
                    if (request.ExportBugReportAfterUnexpectedReplan)
                    {
                        string directory = ProjectSettings.GlobalizePath("user://combat-solver-test-bug-reports");
                        string archivePath = await CombatBugReportExporter.ExportCurrentAsync(directory);
                        using ZipArchive archive = ZipFile.OpenRead(archivePath);
                        AssertBugReportArchive(archive, "current", request.ExpectedBugReportControlMode);
                        runner._completedChecks.Add(
                            $"BugReportAtUnexpectedReplan:{Path.GetFileName(archivePath)}");
                    }
                    stoppedAfterExpectedUnexpectedReplan = true;
                    runner._completedChecks.Add($"UnexpectedReplanWarning:{maximumUnexpectedReplans}");
                    break;
                }
                if (!expectedReuseObserved)
                    expectedReuseObserved = ObserveExpectedReuse();
                if (request.StopAfterExpectedReuse && expectedReuseObserved)
                {
                    stoppedAfterExpectedReuse = true;
                    break;
                }
                if (request.StopAfterExpectedPlayerPower && expectedPlayerPowerObserved)
                {
                    stoppedAfterExpectedPower = true;
                    runner._completedChecks.Add($"PlayerPower:{request.ExpectedObservedPlayerPowerId}");
                    break;
                }
                if (request.ExpectedFullAutoPausedAtDeathTurn
                    && !SolverController.FullAutoEnabled
                    && !SolverController.IsSearching
                    && !SolverController.IsDeploying)
                {
                    stoppedAfterDeathTurnPause = true;
                    runner._completedChecks.Add($"FullAutoPaused:DeathTurn={startedTurn}");
                    break;
                }
                if (request.ExpectedFullAutoPausedAfterWorseRecalculation
                    && SolverController.LastFullAutoStoppedForWorseRecalculationForTesting
                    && !SolverController.IsSearching
                    && !SolverController.IsDeploying)
                {
                    stoppedAfterWorseRecalculationPause = true;
                    runner._completedChecks.Add("FullAutoPaused:WorseRecalculation");
                    break;
                }
                if (request.ExpectedFullAutoPausedAtLiveRisk
                    && SolverController.LastFullAutoStoppedAtLiveRiskForTesting
                    && !SolverController.IsSearching
                    && !SolverController.IsDeploying)
                {
                    stoppedAfterLiveRiskPause = true;
                    runner._completedChecks.Add("FullAutoPaused:LiveEndTurnRisk");
                    break;
                }
                if (request.ExpectedManualDivergencesAtLeast is { } minimumManualDivergences
                    && SolverController.ManualDivergenceCountForTesting >= minimumManualDivergences
                    && (!request.ExpectedNoGcRegionRolloversAtLeast.HasValue
                        || SolverController.NoGcRegionRolloverCountForTesting
                            >= request.ExpectedNoGcRegionRolloversAtLeast.Value))
                {
                    stoppedAfterManualDivergence = true;
                    runner._completedChecks.Add(
                        $"ManualDivergence:{SolverController.ManualDivergenceCountForTesting}");
                    if (request.ExpectedNoGcRegionRolloversAtLeast.HasValue)
                    {
                        stoppedAfterNoGcRollover = true;
                        runner._completedChecks.Add(
                            $"NoGcRegionRollovers:{SolverController.NoGcRegionRolloverCountForTesting}");
                    }
                    break;
                }
                if (request.ExpectedNoGcRegionRolloversAtLeast is { } minimumRollovers
                    && SolverController.NoGcRegionRolloverCountForTesting >= minimumRollovers
                    && (!request.ExpectedManualDivergencesAtLeast.HasValue
                        || SolverController.ManualDivergenceCountForTesting
                            >= request.ExpectedManualDivergencesAtLeast.Value))
                {
                    stoppedAfterNoGcRollover = true;
                    runner._completedChecks.Add(
                        $"NoGcRegionRollovers:{SolverController.NoGcRegionRolloverCountForTesting}");
                    if (request.ExpectedManualDivergencesAtLeast.HasValue)
                    {
                        stoppedAfterManualDivergence = true;
                        runner._completedChecks.Add(
                            $"ManualDivergence:{SolverController.ManualDivergenceCountForTesting}");
                    }
                    break;
                }
                runner.EnsureWithinDeadline();
                await runner.NextFrameAsync();
            }
            expectedCardPlayed |= runner.WasExpectedCardPlayed();
            expectedPotionUsed |= runner.WasExpectedPotionUsed();
            expectedPlayerPowerObserved |= runner.HasExpectedPlayerPower(player);
            maximumUnexpectedReplans = Math.Max(
                maximumUnexpectedReplans,
                SolverController.UnexpectedReplanCountForTesting);
            await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
            while (SolverController.IsDeploying)
            {
                runner.EnsureWithinDeadline();
                await runner.NextFrameAsync();
            }
            if (!expectedReuseObserved)
                expectedReuseObserved = ObserveExpectedReuse();
            if (expectedReuseObserved && request.ExpectedReusedTurn.HasValue)
                runner._completedChecks.Add($"Reuse:Turn={request.ExpectedReusedTurn}");
            if (request.AssertDeploymentSpeedRestored
                && fastModeBeforeDeployment is { } expectedFastMode)
            {
                long restoreDeadline = System.Environment.TickCount64 + 5_000;
                while (SaveManager.Instance.PrefsSave.FastMode != expectedFastMode)
                {
                    runner.EnsureWithinDeadline();
                    if (System.Environment.TickCount64 >= restoreDeadline)
                    {
                        throw new InvalidOperationException(
                            $"自动执行后游戏速度为 {SaveManager.Instance.PrefsSave.FastMode}，" +
                            $"5 秒内没有恢复为 {expectedFastMode}。");
                    }
                    await runner.NextFrameAsync();
                }
            }
            if (request.AssertDeploymentSpeedRestored && fastModeBeforeDeployment.HasValue)
                runner._completedChecks.Add($"DeploymentSpeedRestored:{fastModeBeforeDeployment}");
            if (!expectedReuseObserved)
            {
                throw new InvalidOperationException(
                    $"没有观察到第 {request.ExpectedReusedTurn} 回合复用首轮预测状态。");
            }
            if (request.ExpectedUnexpectedReplansAtMost is { } maximumReplans
                && maximumUnexpectedReplans > maximumReplans)
            {
                throw new InvalidOperationException(
                    $"战斗出现 {maximumUnexpectedReplans} 次非预期重算，超过上限 {maximumReplans}。");
            }
            if (request.ExpectedUnexpectedReplansAtMost.HasValue)
                runner._completedChecks.Add($"UnexpectedReplans:{maximumUnexpectedReplans}");
            if (request.ExpectedUnexpectedReplansAtLeast is { } minimumReplans
                && maximumUnexpectedReplans < minimumReplans)
            {
                throw new InvalidOperationException(
                    $"战斗只出现 {maximumUnexpectedReplans} 次非预期重算，低于预期下限 {minimumReplans}。");
            }
            if (request.ExpectedUnexpectedReplanWarning
                && maximumUnexpectedReplans > 0
                && !stoppedAfterExpectedUnexpectedReplan
                && !SolverOverlay.UnexpectedReplanWarningVisibleForTesting)
            {
                throw new InvalidOperationException("已发生计划外重算，但标题右侧没有显示反馈告警。");
            }

            if (!stoppedAfterExpectedReuse
                && !stoppedAfterExpectedPower
                && !stoppedAfterDeathTurnPause
                && !stoppedAfterWorseRecalculationPause
                && !stoppedAfterLiveRiskPause
                && !stoppedAfterManualDivergence
                && !stoppedAfterNoGcRollover
                && !stoppedAfterExpectedUnexpectedReplan)
            {
                if (request.ExpectedPlayerDeath)
                {
                    if (!player.Creature.IsDead)
                        throw new InvalidOperationException("预期玩家死亡，但战斗结束时玩家仍存活。");
                }
                else if (!combatState.Enemies.All(static enemy => enemy.IsDead))
                {
                    throw new InvalidOperationException("战斗结束，但仍存在未死亡敌人。");
                }
            }
            bool combatEnded = !stoppedAfterExpectedReuse
                && !stoppedAfterExpectedPower
                && !stoppedAfterDeathTurnPause
                && !stoppedAfterWorseRecalculationPause
                && !stoppedAfterLiveRiskPause
                && !stoppedAfterExpectedUnexpectedReplan;
            if (request.ScenarioId == "CHECKPOINT-RECORDED-PLAN-DEPLOYMENT")
                runner.AssertRecordedPlanDeployment(combatState);
            return Observation(combatEnded);

            ExecutionOutcome Observation(bool combatEnded, bool initialSearchHeld = false)
                => new(
                    combatEnded,
                    player.PlayerCombatState?.TurnNumber ?? startedTurn,
                    expectedCardPlayed,
                    expectedPotionUsed,
                    expectedPlayerPowerObserved,
                    initialSearchHeld);
        }

        private FastModeType? ApplySettingsOverrides()
        {
            UnattendedTestRequest request = runner._request;
            if (runner._checkpointImport == null
                && !request.PerformancePresetForTest.HasValue
                && !request.SearchBeamWidthForTest.HasValue
                && !request.SearchMaxExpandedNodesForTest.HasValue
                && !request.ShortMaxCardBranchesPerNodeForTest.HasValue
                && !request.DeepMaxCardBranchesPerNodeForTest.HasValue
                && !request.PotionPolicyForTest.HasValue
                && !request.EnableNoGcRegionForTest.HasValue
                && !request.NoGcRegionBudgetGigabytesForTest.HasValue
                && !request.DeploymentFastModeForTest.HasValue
                && !request.DeploymentInterActionDelaySecondsForTest.HasValue
                && !request.EnableDetailedDiagnosticLogsForTest.HasValue)
            {
                return null;
            }

            _settingsBeforeTest ??= SolverSettings.Current;
            SolverSettingsData recordedSettings = runner.ApplyRecordedCheckpointPolicy(_settingsBeforeTest);
            SolverSettingsData testSettings = request.PerformancePresetForTest is { } preset
                ? SolverSettings.ApplyPerformancePreset(recordedSettings, preset)
                : recordedSettings;
            bool hasCustomPerformanceOverride = request.ShortMaxCardBranchesPerNodeForTest.HasValue
                || request.DeepMaxCardBranchesPerNodeForTest.HasValue
                || request.SearchBeamWidthForTest.HasValue
                || request.SearchMaxExpandedNodesForTest.HasValue;
            if (request.SearchBeamWidthForTest is < 1 or > 512)
                throw new ArgumentOutOfRangeException(nameof(request.SearchBeamWidthForTest));
            if (request.SearchMaxExpandedNodesForTest is < 100)
                throw new ArgumentOutOfRangeException(nameof(request.SearchMaxExpandedNodesForTest));
            if (request.SearchBeamWidthForTest.HasValue || request.SearchMaxExpandedNodesForTest.HasValue)
            {
                testSettings = SolverSettings.ApplyPerformancePreset(testSettings, SolverPerformancePreset.Custom);
                testSettings = testSettings with
                {
                    PerformancePreset = SolverPerformancePreset.Custom,
                    SearchBeamWidth = request.SearchBeamWidthForTest ?? testSettings.SearchBeamWidth,
                    SearchMaxExpandedNodes = request.SearchMaxExpandedNodesForTest ?? testSettings.SearchMaxExpandedNodes,
                };
            }
            if (request.NoGcRegionBudgetGigabytesForTest is { } noGcBudget)
            {
                testSettings = testSettings with
                {
                    NoGcRegionBudgetGigabytes = noGcBudget,
                };
            }
            if (request.ShortMaxCardBranchesPerNodeForTest is { } shortMaxCardBranches)
            {
                testSettings = testSettings with
                {
                    PerformancePreset = SolverPerformancePreset.Custom,
                    SearchMaxCardBranchesPerNode = shortMaxCardBranches,
                };
            }
            if (request.DeepMaxCardBranchesPerNodeForTest is { } deepMaxCardBranches)
            {
                testSettings = testSettings with
                {
                    PerformancePreset = SolverPerformancePreset.Custom,
                    SearchMaxCardBranchesPerNode = deepMaxCardBranches,
                };
            }
            SolverSettings.ApplyForTesting(testSettings with
            {
                EnableNoGcRegion = request.EnableNoGcRegionForTest
                    ?? testSettings.EnableNoGcRegion,
                DeploymentFastMode = request.DeploymentFastModeForTest
                    ?? _settingsBeforeTest.DeploymentFastMode,
                DeploymentInterActionDelaySeconds = request.DeploymentInterActionDelaySecondsForTest
                    ?? _settingsBeforeTest.DeploymentInterActionDelaySeconds,
                EnableDetailedDiagnosticLogs = request.EnableDetailedDiagnosticLogsForTest
                    ?? _settingsBeforeTest.EnableDetailedDiagnosticLogs,
                PotionPolicy = request.PotionPolicyForTest
                    ?? testSettings.PotionPolicy,
            });
            FastModeType fastModeBeforeDeployment = SaveManager.Instance.PrefsSave.FastMode;
            if (request.PerformancePresetForTest is { } expectedPreset)
            {
                runner.AssertPerformancePreset(
                    hasCustomPerformanceOverride
                        ? SolverPerformancePreset.Custom
                        : expectedPreset);
            }
            SolverSettingsSnapshot snapshot = SolverSettings.Capture();
            if (request.SearchBeamWidthForTest is { } expectedBeam
                && snapshot.Profile.BeamWidth != expectedBeam)
                throw new InvalidOperationException($"测试 Beam 为 {snapshot.Profile.BeamWidth}，预期 {expectedBeam}。");
            if (request.SearchMaxExpandedNodesForTest is { } expectedNodes
                && snapshot.Profile.MaxExpandedNodes != expectedNodes)
                throw new InvalidOperationException($"测试节点额度为 {snapshot.Profile.MaxExpandedNodes}，预期 {expectedNodes}。");
            if (runner._writer.ReplayVerification != null)
                runner._writer.ReplayVerification["executedPolicy"] = System.Text.Json.JsonSerializer.SerializeToNode(
                    new { snapshot.PotionPolicy, SolverSettings.Current.PotionDirectives,
                        snapshot.ActTransitionBossHpStrategy, snapshot.FinalBossHpStrategy,
                        snapshot.Profile, snapshot.SearchMaxDegreeOfParallelism },
                    UnattendedTestFiles.JsonOptions);
            if (request.EnableNoGcRegionForTest is { } expectedNoGcEnabled
                && snapshot.EnableNoGcRegion != expectedNoGcEnabled)
            {
                throw new InvalidOperationException(
                    $"No-GC 开关为 {snapshot.EnableNoGcRegion}，预期 {expectedNoGcEnabled}。");
            }
            if (request.ShortMaxCardBranchesPerNodeForTest is { } expectedShortBranches
                && snapshot.Profile.MaxCardBranchesPerNode != expectedShortBranches)
            {
                throw new InvalidOperationException(
                    $"短搜单节点出牌分支为 {snapshot.Profile.MaxCardBranchesPerNode}，" +
                    $"预期 {expectedShortBranches}。");
            }
            if (request.DeepMaxCardBranchesPerNodeForTest is { } expectedDeepBranches
                && snapshot.Profile.MaxCardBranchesPerNode != expectedDeepBranches)
            {
                throw new InvalidOperationException(
                    $"深搜单节点出牌分支为 {snapshot.Profile.MaxCardBranchesPerNode}，" +
                    $"预期 {expectedDeepBranches}。");
            }
            if (request.NoGcRegionBudgetGigabytesForTest is { } expectedNoGcGigabytes)
            {
                long expectedNoGcBytes = checked((long)Math.Round(
                    expectedNoGcGigabytes * 1_000_000_000d,
                    MidpointRounding.AwayFromZero));
                if (snapshot.NoGcRegionBudgetBytes != expectedNoGcBytes)
                {
                    throw new InvalidOperationException(
                        $"No-GC 预算为 {snapshot.NoGcRegionBudgetBytes}，预期 {expectedNoGcBytes}。");
                }
            }
            return fastModeBeforeDeployment;
        }
    }
}

tools/inspection/verify-refactor-boundar.source:
#requires -Version 7.0

$ErrorActionPreference = "Stop"
$repositoryRoot = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$searchRoot = Join-Path $repositoryRoot "src\Search"

$forbiddenSearchReferences = @(
    "SolverSearchPhase",
    "ShortProfile",
    "DeepProfile",
    "shortCheckpointMilliseconds",
    "SolveWithNarrowBeamRecovery",
    "BuildNarrowBeamRecoveryProfile",
    "RecoverDeferredTurnFrontier",
    "DeferredTurnFrontier",
    "SolverSettings.Current",
    "Entry.Logger",
    "SolverController",
    "SolverOverlay",
    "SolverText",
    "SolverRelicEffectText",
    "SolverUiModelNames",
    "SolverActionTextIdentity",
    "SolverLocaleRefresh",
    "SolvedRouteCache",
    "RunStatistics",
    "UnattendedTestRunner"
)

$violations = [System.Collections.Generic.List[string]]::new()
foreach ($relative in @('tools/search/StrategyCorpus/run.py', 'tools/search/StrategyCorpus/compare.py', 'coverage/corpora/strategy/p0.json')) {
    if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot $relative) -PathType Leaf)) {
        $violations.Add("Strategy corpus input missing: $relative")
    }
}
foreach ($relative in @('src/Search/RouteQuality.cs', 'src/Search/RouteQualityPolicy.cs')) {
    if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot $relative) -PathType Leaf)) {
        $violations.Add("Route quality model missing: $relative")
    }
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/PotionValuationRegistry.cs') -PathType Leaf)) {
    $violations.Add('Potion valuation registry missing')
}
$potionPolicySource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/PotionUsePolicy.cs') -Raw
if (-not $potionPolicySource.Contains('PotionValuationRegistry.Default') -or
    $potionPolicySource.Contains('HighValuePotionIds') -or
    $potionPolicySource.Contains('ElevatedValuePotionIds')) {
    $violations.Add('Potion valuation classifications remain outside the registry')
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/OpeningActionRegistry.cs') -PathType Leaf)) {
    $violations.Add('Opening action registry missing')
}
$openingSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.Expansion.Opening.cs') -Raw
if (-not $openingSource.Contains('OpeningActionRegistry.Default') -or
    $openingSource -match '"(?:WHITE_NOISE|NIGHTMARE|DUPLICATOR)"') {
    $violations.Add('Opening action IDs remain outside the registry')
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/TargetPlanRegistry.cs') -PathType Leaf) -or
    -not $openingSource.Contains('TargetPlanRegistry.Default')) {
    $violations.Add('Opening target plans are not registered')
}
$strategyIdLiteralCount = 0
foreach ($sourceFile in Get-ChildItem -LiteralPath (Join-Path $repositoryRoot 'src/Search') -Filter '*.cs' -Recurse) {
    if ($sourceFile.Name -in @('PotionValuationRegistry.cs', 'OpeningActionRegistry.cs', 'TargetPlanRegistry.cs')) {
        continue
    }
    $strategyIdLiteralCount += [regex]::Matches(
        [System.IO.File]::ReadAllText($sourceFile.FullName), '"[A-Z][A-Z0-9_]{4,}"').Count
}
if ($strategyIdLiteralCount -gt 645) {
    $violations.Add("Search strategy ID literals increased: $strategyIdLiteralCount > 645")
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.ExpansionPlan.cs') -PathType Leaf)) {
    $violations.Add('Shared expansion plan missing')
}
$serialExpansionSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.Expansion.cs') -Raw
$parallelExpansionSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.ParallelExpansion.cs') -Raw
if (-not $serialExpansionSource.Contains('cardJobs.PrepareSerialCards(this,') -or
    -not $parallelExpansionSource.Contains('EnumeratePlannedCardActions(') -or
    -not $serialExpansionSource.Contains('cardJobs.PrepareSerialPotions(this)') -or
    -not $parallelExpansionSource.Contains('EnumeratePlannedPotionActions(')) {
    $violations.Add('Serial and parallel card/potion paths do not share the expansion plan')
}
if (-not $serialExpansionSource.Contains('cardJobs.RunSerialCardAction(this, cardJob)') -or
    -not $serialExpansionSource.Contains('CreatePlannedPotionChild(') -or
    -not $parallelExpansionSource.Contains('CreatePlannedCardChild(') -or
    -not $parallelExpansionSource.Contains('CreatePlannedPotionChild(')) {
    $violations.Add('Card and potion children must use the shared construction path')
}
if (-not $serialExpansionSource.Contains('cardJobs.RunSerialCardAction(this, cardJob)') -or
    -not $parallelExpansionSource.Contains('TryResolvePlannedCardChoices(')) {
    $violations.Add('Serial and parallel paths must share ordinary card choice dispatch')
}
if (-not $serialExpansionSource.Contains('TryAdmitExpansionParent(') -or
    -not $parallelExpansionSource.Contains('TryAdmitExpansionParent(')) {
    $violations.Add('Serial and parallel paths duplicate parent expansion admission')
}
if (-not $serialExpansionSource.Contains('ProcessExpandedCardCandidate(') -or
    -not $parallelExpansionSource.Contains('ProcessExpandedCardCandidate(') -or
    $parallelExpansionSource.Contains('AddNonDominatedParallelCandidate(')) {
    $violations.Add('Serial and parallel card admission remains duplicated')
}
$expansionPlanSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.ExpansionPlan.cs') -Raw
if (-not $expansionPlanSource.Contains('IEnumerable<PreparedCardAction> EnumeratePlannedCardActions(') -or
    $expansionPlanSource.Contains('PredictedCard? sourceCard') -or
    -not $serialExpansionSource.Contains('cardJobs.RunSerialCardAction(this, cardJob)') -or
    $serialExpansionSource.Contains('TryResolvePlannedCardChoices(') -or
    -not $parallelExpansionSource.Contains('TryResolvePlannedCardChoices(node, action, probeSnapshot,')) {
    $violations.Add('Card choice replay and requirements must use the shared planned action path')
}
if (-not $expansionPlanSource.Contains('TryAdmitPlannedPotionChild(') -or
    -not $serialExpansionSource.Contains('TryAdmitPlannedPotionChild(') -or
    -not $parallelExpansionSource.Contains('TryAdmitPlannedPotionChild(')) {
    $violations.Add('Serial and parallel potion admission remains duplicated')
}
if (-not $expansionPlanSource.Contains('AdmitPlannedEndTurnChildren(') -or
    -not $serialExpansionSource.Contains('AdmitPlannedEndTurnChildren(cycleExitBatch)') -or
    -not $serialExpansionSource.Contains('AdmitPlannedEndTurnChildren(batch)') -or
    -not $parallelExpansionSource.Contains('AdmitPlannedEndTurnChildren(batch)')) {
    $violations.Add('End-turn candidate admission has multiple owners')
}
$executorPath = Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.ExpansionExecutor.cs'
$phasesSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.Phases.cs') -Raw
$admittedExpansionSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.AdmittedExpansion.cs') -Raw
if ($admittedExpansionSource -notmatch '(?m)^    }\r?\n\s*\r?\n    private readonly record struct ChoiceJob\(' -or
    $admittedExpansionSource -notmatch '(?m)^    private sealed class AdmittedParent\(' -or
    -not $admittedExpansionSource.Contains('private sealed class AdmittedJobScheduler(') -or
    -not $admittedExpansionSource.Contains('public void RunSerialCardAction(CombatBeamSolver solver, AdmittedExpansionJob job)') -or
    -not $admittedExpansionSource.Contains('public void RunSerialChoiceJob(CombatBeamSolver solver, AdmittedExpansionJob job)') -or
    -not $admittedExpansionSource.Contains('public IEnumerable<SearchNode> RunSerialPotionJob(') -or
    -not $admittedExpansionSource.Contains('public IEnumerable<SearchNode> RunSerialEndTurnJob(') -or
    -not $admittedExpansionSource.Contains('scheduler.NextJob(laneIndex)') -or
    $admittedExpansionSource.Contains('AdmittedExpansionJob? NextJob(int laneIndex)') -or
    -not $serialExpansionSource.Contains('scheduler.NextJob(0, SerialJobPhase.Prepare)') -or
    -not $serialExpansionSource.Contains('scheduler.NextJob(0, SerialJobPhase.Card)') -or
    -not $serialExpansionSource.Contains('scheduler.NextJob(0, SerialJobPhase.Potion)') -or
    -not $serialExpansionSource.Contains('scheduler.NextJob(0, SerialJobPhase.Tail)')) {
    $violations.Add('Admitted parent job state must belong to CombatBeamSolver, outside the parallel executor')
}
if (-not $parallelExpansionSource.Contains('private sealed class PreparedPotionChoiceWork(') -or
    -not $parallelExpansionSource.Contains('work.Resolve(this, node, baseAction)') -or
    -not $serialExpansionSource.Contains('work.Resolve(this, node, planned.Action)')) {
    $violations.Add('Serial and parallel potion choice replay must use the same prepared work owner')
}
if (-not (Test-Path -LiteralPath $executorPath -PathType Leaf) -or
    -not ([System.IO.File]::ReadAllText($executorPath)).Contains('private interface IExpansionExecutor') -or
    -not ([System.IO.File]::ReadAllText($executorPath)).Contains('private sealed class SerialExpansionExecutor') -or
    -not $parallelExpansionSource.Contains('ParallelExpansionExecutor : IExpansionExecutor') -or
    -not $phasesSource.Contains('serialExpansionExecutor.Execute(') -or
    -not $phasesSource.Contains('parallelExpansionExecutor!.Execute(')) {
    $violations.Add('Serial and parallel expansion do not share the executor contract')
}
$workTotalsSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/SearchRequestWorkTotals.cs') -Raw
$beamSolverSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.cs') -Raw
$coordinatorSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.cs') -Raw
if (-not $workTotalsSource.Contains('DirectSearchPurpose') -or
    -not $beamSolverSource.Contains('DirectSearchPurpose? directSearchPurpose') -or
    -not $coordinatorSource.Contains('DirectSearchPurpose.RefinementBeam') -or
    -not $coordinatorSource.Contains('DirectSearchPurpose.PrimaryBeam')) {
    $violations.Add('Primary and refinement Beam work attribution missing')
}
$auditSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.Audits.cs') -Raw
$postSearchSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.PostSearch.cs') -Raw
$earlyTurnSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.EarlyTurnExploration.cs') -Raw
$noveltySource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.NoveltyPortfolio.cs') -Raw
if (-not $coordinatorSource.Contains('DirectSearchPurpose.PotionFreeAudit') -or
    -not $auditSource.Contains('DirectSearchPurpose.PotionFreeAudit') -or
    -not $auditSource.Contains('DirectSearchPurpose.RequiredPotionAudit') -or
    -not $auditSource.Contains('DirectSearchPurpose.SmartPotionGradient') -or
    -not $postSearchSource.Contains('DirectSearchPurpose.TurnBoundaryDiscovery') -or
    -not $earlyTurnSource.Contains('DirectSearchPurpose.EarlyTurnScout') -or
    -not $noveltySource.Contains('DirectSearchPurpose.NoveltyExploration') -or
    -not $noveltySource.Contains('DirectSearchPurpose.AdaptiveNoveltyRefinement')) {
    $violations.Add('Direct search work attribution missing')
}
foreach ($relative in @('src/Search/PlanCommitment.cs', 'src/Search/PlanMechanismRegistry.cs', 'src/Search/CombatSearchCoordinator.PlanSearch.cs')) {
    if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot $relative) -PathType Leaf)) {
        $violations.Add("Plan search boundary missing: $relative")
    }
}
$planSearchSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.PlanSearch.cs') -Raw
if (-not $planSearchSource.Contains('context.Budget.RequestWindow(') -or
    -not $planSearchSource.Contains('ContinuationPurpose.PlanCommitment') -or
    -not $planSearchSource.Contains('IsBetterPotionPolicyResult(') -or
    -not $planSearchSource.Contains('TryRunPlanMember(')) {
    $violations.Add('Plan search bypasses shared budget, continuation or final quality policy')
}
if (-not $planSearchSource.Contains('PlanMechanismRegistry.Default.DeferredCopies') -or
    -not $planSearchSource.Contains('BuildOpeningCopyActionsAfterPrefix(') -or
    $planSearchSource.Contains('PlanChoiceEffect.Nightmare') -or
    $planSearchSource.Contains('OpeningCandidatePurpose.NightmareCopyCard') -or
    -not $openingSource.Contains('HasPlayableChoiceEffect(')) {
    $violations.Add('Plan copy discovery must follow registered choice semantics')
}
$planMechanismSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/PlanMechanismRegistry.cs') -Raw
if (-not $planMechanismSource.Contains('ImmutableArray<DeferredCopyPlanRule>') -or
    -not $planMechanismSource.Contains('PlanChoiceEffect.Nightmare')) {
    $violations.Add('Deferred copy plan rules must be internally immutable and registered')
}
$planCommitmentSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/PlanCommitment.cs') -Raw
if (-not $planCommitmentSource.Contains('PlanPayoffEvidenceKind') -or
    -not $planCommitmentSource.Contains('FreePotionUsed') -or
    -not $planCommitmentSource.Contains('RegisteredPowerBenefit') -or
    $planCommitmentSource.Contains('PayoffCardId')) {
    $violations.Add('Plan payoff evidence must be typed and shared across mechanisms')
}
$potionChainSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.PotionChain.cs') -Raw
if (-not $potionChainSource.Contains('PlanCommitmentKind.PotionChain') -or
    -not $potionChainSource.Contains('PlanPayoffEvidenceKind.FreePotionUsed') -or
    -not $potionChainSource.Contains('Commitment = plan')) {
    $violations.Add('Generated free-potion chain must carry plan payoff evidence')
}
$postSearchSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.PostSearch.cs') -Raw
if (-not $postSearchSource.Contains('RunDeferredPowerPlanSearchPass(') -or
    -not $planSearchSource.Contains('EarlyTurnScoutDepth = 1') -or
    -not $planSearchSource.Contains('PlanCommitmentKind.CrossTurnBenefit')) {
    $violations.Add('Deferred power plan must use the ordered post-search continuation')
}
$planRetentionSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.BeamRetentionPolicy.cs') -Raw
if (-not $planRetentionSource.Contains('AdmitPlanCommitmentRepresentatives(') -or
    -not $planRetentionSource.Contains('_planCommitment')) {
    $violations.Add('Plan commitment has no protected retention representatives')
}
$crossTurnSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatBeamSolver.Expansion.cs') -Raw
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/PlanHorizonPolicy.cs') -PathType Leaf) -or
    -not $crossTurnSource.Contains('PlanHorizonPolicy.ShouldExtend(')) {
    $violations.Add('Realized plans have no bounded horizon extension')
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/SearchBudgetLedger.cs') -PathType Leaf)) {
    $violations.Add('Search budget ledger missing')
}
$budgetSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/SearchBudgetLedger.cs') -Raw
if (-not $budgetSource.Contains('internal readonly record struct SearchBudgetWindow') -or
    -not $budgetSource.Contains('internal SearchBudgetWindow RequestWindow(')) {
    $violations.Add('Request budget window missing')
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/SearchPassContext.cs') -PathType Leaf)) {
    $violations.Add('Search pass context missing')
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/SearchPassResult.cs') -PathType Leaf)) {
    $violations.Add('Search pass result missing')
}
$passResultSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/SearchPassResult.cs') -Raw
foreach ($field in @('RouteQuality? Quality', 'SearchRequestWorkSnapshot WorkTotals',
        'SolverResultScope PassScope', 'SearchBoundaryReason PassBoundary')) {
    if (-not $passResultSource.Contains($field)) {
        $violations.Add("Search pass result contract missing: $field")
    }
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/SearchRequestPipeline.cs') -PathType Leaf)) {
    $violations.Add('Search request pipeline missing')
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.PostSearch.cs') -PathType Leaf)) {
    $violations.Add('Post-search passes missing')
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.BeamPortfolio.cs') -PathType Leaf)) {
    $violations.Add('Beam portfolio owner missing')
}
if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.Audits.cs') -PathType Leaf)) {
    $violations.Add('Supplemental audit owner missing')
}
foreach ($relative in @('src/Search/FrontierContinuationScheduler.cs',
        'src/Search/OpeningPotionPairContinuationSource.cs',
        'src/Search/EarlierCopyDelayedDamageContinuationSource.cs',
        'src/Search/OpeningNoCostContinuationSource.cs',
        'src/Search/TurnEndChoiceContinuationSource.cs',
        'src/Search/SinglePrefixContinuationSource.cs',
        'src/Search/TurnBoundaryContinuationSource.cs')) {
    if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot $relative) -PathType Leaf)) {
        $violations.Add("Frontier continuation component missing: $relative")
    }
}
$coordinatorSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.cs') -Raw
$auditSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.Audits.cs') -Raw
if (($coordinatorSource -split '\r?\n').Count -gt 1201) {
    $violations.Add('Search coordinator main file exceeds the P3 1200-line ownership limit')
}
if (-not $coordinatorSource.Contains('SearchBudgetLedger ledger = new(')) {
    $violations.Add('Search coordinator does not own a request budget ledger')
}
if ($coordinatorSource.Contains('- (int)passClock.ElapsedMilliseconds') -or
    $coordinatorSource.Contains('policy.RequestWorkTotals?.Snapshot().ExpandedNodes ?? 0L')) {
    $violations.Add('Primary pass prefix budgets bypass the request budget ledger')
}
if ($coordinatorSource.Contains('MaxExpandedNodes = (int)Math.Min(')) {
    $violations.Add('Primary pass member budget bypasses the pass budget window')
}
foreach ($purpose in @('EarlyDiscardBeforeGeneration', 'OpeningTargetVariant',
        'OpeningTargetPowerVariant', 'OpeningTargetPowerDefensiveVariant',
        'DeferredOpeningPower', 'FreeAttackHandSetup')) {
    if (-not $coordinatorSource.Contains("ContinuationPurpose.$purpose")) {
        $violations.Add("Primary pass fixed-prefix request missing: $purpose")
    }
}
foreach ($purpose in @('OpeningResourceDefense', 'PotionResourcePosterior',
        'PotionPowerPosterior', 'PotionPowerDefensivePosterior')) {
    if (-not $auditSource.Contains("ContinuationPurpose.$purpose")) {
        $violations.Add("Opening audit fixed-prefix request missing: $purpose")
    }
}
foreach ($purpose in @('RequiredOpeningPotion', 'RequiredPotionPair',
        'RequiredPotionPairDefensive')) {
    if (-not $auditSource.Contains("ContinuationPurpose.$purpose")) {
        $violations.Add("Required potion audit fixed-prefix request missing: $purpose")
    }
}
if ($coordinatorSource.Contains('fixedPrefixActions:')) {
    $violations.Add('Search coordinator constructs a fixed-prefix solver outside the scheduler')
}
if ($coordinatorSource.Contains('SearchRequestWorkTotals requestWorkTotals = new()')) {
    $violations.Add('Search coordinator creates request work totals outside the budget ledger')
}
if (-not $coordinatorSource.Contains('RunSupplementalAudits(auditContext,')) {
    $violations.Add('Supplemental audits do not consume the search pass context')
}
if (-not $coordinatorSource.Contains('SearchPassResult RunSearchPass(')) {
    $violations.Add('Search pass does not return its termination state')
}
if (-not $coordinatorSource.Contains('SearchPassResult RunSearchPass(SearchPassContext passContext)') -or
    -not $coordinatorSource.Contains('new SearchRequestPipeline(requestContext, RunSearchPass, postSearch).Run()')) {
    $violations.Add('Primary search pass does not consume the search pass context')
}
$postSearchSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/CombatSearchCoordinator.PostSearch.cs') -Raw
if (-not $postSearchSource.Contains('RunEarlyPotionPairRescue(context, selected)') -or
    -not $postSearchSource.Contains('RunEarlyPotionPairRescue(SearchPassContext context, SolverResult selected)') -or
    $coordinatorSource.Contains('EARLY_POTION_PAIR prefix=')) {
    $violations.Add('Early potion pair rescue is not a post-search pass')
}
$continuationSchedulerSource = Get-Content -LiteralPath (Join-Path $repositoryRoot 'src/Search/FrontierContinuationScheduler.cs') -Raw
if (-not $postSearchSource.Contains('new FrontierContinuationScheduler(context).Run(') -or
    -not $continuationSchedulerSource.Contains('RequestWindow(') -or
    -not $continuationSchedulerSource.Contains('fixedPrefixActions: request.Prefix')) {
    $violations.Add('Early potion pair rescue bypasses the frontier continuation scheduler')
}
if (-not $continuationSchedulerSource.Contains('SolverResult Dispatch(ContinuationSearchRequest request)') -or
    -not $continuationSchedulerSource.Contains('result = Dispatch(request);') -or
    -not $continuationSchedulerSource.Contains('CombatBeamSolver CreateSolver(ContinuationSearchRequest request)')) {
    $violations.Add('Frontier continuation request does not own solver construction')
}
if (-not $postSearchSource.Contains('new EarlierCopyDelayedDamageContinuationSource(') -or
    -not $postSearchSource.Contains('context, selected.BestNode.Actions)')) {
    $violations.Add('Earlier copy potion rescue bypasses the frontier continuation scheduler')
}
if (-not $postSearchSource.Contains('OpeningNoCostContinuationSource source = new(context);') -or
