using System.Diagnostics;
using System.Collections.Frozen;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Context;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Localization.DynamicVars;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Powers;
using MegaCrit.Sts2.Core.Nodes;
using MegaCrit.Sts2.Core.Models.Relics;
using MegaCrit.Sts2.Core.Rooms;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;

namespace CombatSolver;

internal readonly record struct SearchablePotionSlotSnapshot(
    int Slot,
    string PotionId,
    int StrategicHpCost);

internal sealed class CombatRootSnapshot
{
    private readonly CombatPredictionSimulator _rootSimulator;

    public Player PlayerIdentity { get; }
    public IReadOnlyList<Creature> Enemies { get; }
    public IntentForecast Forecast { get; }
    public LiveCombatStamp LiveStamp { get; }
    public ContinuationStamp ContinuationStamp { get; }
    public int PlayerCount { get; }
    public int StartTurnNumber { get; }
    public int TotalFloor { get; }
    public int InitialPlayerHp { get; }
    public int InitialPlayerMaxHp { get; }
    public int InitialBrightestFlameMaxHpSpent
        => ((SimulatedCombatState)_rootSimulator.State.CombatState).BrightestFlameMaxHpSpent;
    public int PotionSlotCount { get; }
    public IReadOnlyList<SearchablePotionSlotSnapshot> SearchablePotions { get; }
    public int SearchablePotionCount { get; }
    public int? MinimumSearchablePotionStrategicCost { get; }
    public int ZeroCostSearchablePotionCount { get; }
    public ulong InitialAliveEnemyMask { get; }
    public CombatSide CurrentSide { get; }
    public PlayerTurnPhase PlayerPhase { get; }
    public RoomType? EncounterRoomType { get; }
    public BossHpRelief BossHpRelief { get; }
    public bool IsActEndingBoss => BossHpRelief != BossHpRelief.None;
    public double CaptureElapsedMilliseconds { get; }
    public int CapturedCardCount { get; }
    public IReadOnlySet<string> PlayerCardIds { get; }
    /// <summary>Conservative recovery metadata for portfolio stopping, not a bound on all future healing.</summary>
    public bool HasVisibleHealingSource { get; }
    public bool HasOnlyPostCombatHealing { get; }
    public string HealingBoundCertificationReason { get; }
    public string? HealingBoundCertificationSourceId { get; }
    public bool CanCertifyRemainingHealing { get; }
    internal bool UsesComponentHealingCertificate { get; }
    internal bool UsesReviewedHealingComponents { get; }
    internal bool HasOriginalHealingCertificate { get; }
    internal string? ComponentHealingRejection { get; }
    public bool UsesKnownNativeHealingPolicy { get; }
    internal GrowthValues InitialGrowthRewards
        => ((SimulatedCombatState)_rootSimulator.State.CombatState).GrowthRewards;
    internal GrowthValues? ExhaustingGrowthUpperBound { get; }
    /// <summary>Root card/power/potion healing bound, excluding fixed post-combat healing.</summary>
    public int InitialRemainingHealingUpperBound { get; }
    public CombatHistoryDependencies HistoryDependencies { get; }
    public int CapturedPowerCount { get; }
    public int CapturedHookListenerCount { get; }
    public int CapturedRunModSubscriberCount { get; }
    public int CapturedCombatModSubscriberCount { get; }
    public bool CapturedBaseLibCardModifiers { get; }
    public bool HasUnusedCardReplayAllocator { get; }
    public bool HasRenewablePotionShapedRock { get; }
    public PostCombatRelicHealProfile PostCombatRelicHeal { get; }
    public PotionRewardOutlook PotionRewardOutlook { get; }
    internal HookLayoutCacheStatistics HookLayoutCacheStatistics
        => ((SimulatedCombatState)_rootSimulator.State.CombatState).HookLayoutCacheStatistics;
    internal HookListenerSegmentStatistics HookListenerSegmentStatistics
        => ((SimulatedCombatState)_rootSimulator.State.CombatState).HookListenerSegmentStatistics;

    private CombatRootSnapshot(
        Player playerIdentity,
        IReadOnlyList<Creature> enemies,
        IntentForecast forecast,
        LiveCombatStamp liveStamp,
        ContinuationStamp continuationStamp,
        CombatPredictionSimulator rootSimulator,
        int playerCount,
        int startTurnNumber,
        int totalFloor,
        int initialPlayerHp,
        int initialPlayerMaxHp,
        int potionSlotCount,
        IReadOnlyList<SearchablePotionSlotSnapshot> searchablePotions,
        ulong initialAliveEnemyMask,
        CombatSide currentSide,
        PlayerTurnPhase playerPhase,
        RoomType? encounterRoomType,
        BossHpRelief bossHpRelief,
        double captureElapsedMilliseconds,
        int capturedCardCount,
        IReadOnlySet<string> playerCardIds,
        bool hasVisibleHealingSource,
        StrategicHpRecoveryBoundAssessment healingBoundAssessment,
        CombatHistoryDependencies historyDependencies,
        int capturedPowerCount,
        int capturedHookListenerCount,
        int capturedRunModSubscriberCount,
        int capturedCombatModSubscriberCount,
        bool capturedBaseLibCardModifiers,
        bool hasUnusedCardReplayAllocator,
        bool hasRenewablePotionShapedRock,
        PostCombatRelicHealProfile postCombatRelicHeal,
        PotionRewardOutlook potionRewardOutlook)
    {
        PlayerIdentity = playerIdentity;
        Enemies = enemies;
        Forecast = forecast;
        LiveStamp = liveStamp;
        ContinuationStamp = continuationStamp;
        _rootSimulator = rootSimulator;
        PlayerCount = playerCount;
        StartTurnNumber = startTurnNumber;
        TotalFloor = totalFloor;
        InitialPlayerHp = initialPlayerHp;
        InitialPlayerMaxHp = initialPlayerMaxHp;
        PotionSlotCount = potionSlotCount;
        SearchablePotions = searchablePotions;
        SearchablePotionCount = searchablePotions.Count;
        MinimumSearchablePotionStrategicCost = searchablePotions.Count == 0
            ? null
            : searchablePotions.Min(potion => potion.StrategicHpCost);
        ZeroCostSearchablePotionCount = searchablePotions.Count(potion =>
            potion.StrategicHpCost == 0);
        InitialAliveEnemyMask = initialAliveEnemyMask;
        CurrentSide = currentSide;
        PlayerPhase = playerPhase;
        EncounterRoomType = encounterRoomType;
        BossHpRelief = bossHpRelief;
        CaptureElapsedMilliseconds = captureElapsedMilliseconds;
        CapturedCardCount = capturedCardCount;
        PlayerCardIds = playerCardIds;
        HasVisibleHealingSource = hasVisibleHealingSource;
        HasOnlyPostCombatHealing = healingBoundAssessment.IsCertified;
        HealingBoundCertificationReason = healingBoundAssessment.Reason;
        HealingBoundCertificationSourceId = healingBoundAssessment.BlockingSourceId;
        ComponentHealingRejection = StrategicHpRecoveryBound.ComponentHealingRejection(rootSimulator, playerIdentity);
        HasOriginalHealingCertificate = ComponentHealingRejection is null
            || StrategicHpRecoveryBound.CanCertifyRemainingHealingEnvironment(rootSimulator, playerIdentity);
        if (ComponentHealingRejection is not null)
        {
            ComponentHealingRejection = StrategicHpRecoveryBound.ComponentHealingRejection(
                rootSimulator, playerIdentity, useReviewedSources: true);
            UsesReviewedHealingComponents = ComponentHealingRejection is null;
        }
        UsesComponentHealingCertificate = ComponentHealingRejection is null;
        CanCertifyRemainingHealing = UsesComponentHealingCertificate || HasOriginalHealingCertificate;
        UsesKnownNativeHealingPolicy = StrategicHpRecoveryBound.CanUseKnownNativeHealingPolicy(
            rootSimulator, playerIdentity);
        ExhaustingGrowthUpperBound = ResourceIncumbentPolicy.CaptureExhaustingGrowthUpperBound(
            rootSimulator, playerIdentity);
        InitialRemainingHealingUpperBound = CanCertifyRemainingHealing
            ? UsesComponentHealingCertificate
                ? StrategicHpRecoveryBound.ComponentHealingUpperBound(rootSimulator, playerIdentity, postCombatHeal: 0,
                    useReviewedSources: UsesReviewedHealingComponents)
                : StrategicHpRecoveryBound.RemainingHealingUpperBound(rootSimulator, playerIdentity, postCombatHeal: 0)
            : int.MaxValue;
        Entry.Logger.Info($"[CombatSolver/Test] REVIEWED_HEALING_PROOF original={HasOriginalHealingCertificate} "
            + $"component={UsesComponentHealingCertificate} reviewed={UsesReviewedHealingComponents} "
            + $"bound={InitialRemainingHealingUpperBound} reason={ComponentHealingRejection ?? "certified"}");
        HistoryDependencies = historyDependencies;
        CapturedPowerCount = capturedPowerCount;
        CapturedHookListenerCount = capturedHookListenerCount;
        CapturedRunModSubscriberCount = capturedRunModSubscriberCount;
        CapturedCombatModSubscriberCount = capturedCombatModSubscriberCount;
        CapturedBaseLibCardModifiers = capturedBaseLibCardModifiers;
        HasUnusedCardReplayAllocator = hasUnusedCardReplayAllocator;
        HasRenewablePotionShapedRock = hasRenewablePotionShapedRock;
        PostCombatRelicHeal = postCombatRelicHeal;
        PotionRewardOutlook = potionRewardOutlook;
    }

    public static CombatRootSnapshot Capture(CombatState state, bool predictPotionReward = false)
    {
        if (!NGame.IsMainThread())
            throw new InvalidOperationException("Combat root snapshot must be captured on the main thread.");
        Engine.InCombat.Mirrors.Hooks.TurnEnd.AfterSideTurnEndLateMirrors.Seal();
        Engine.InCombat.Mirrors.Hooks.TurnStart.BeforeSideTurnStartMirrors.Seal();
        Engine.InCombat.Mirrors.Hooks.TurnStart.AfterPlayerTurnStartMirrors.Seal();
        Engine.InCombat.Mirrors.Hooks.TurnEnd.ExtraTurnMirrors.Seal();
        Stopwatch stopwatch = Stopwatch.StartNew();

        PredictionModPatchAudit.ValidateMonsterModels(state.Enemies.Select(enemy => enemy.Monster).OfType<MonsterModel>());

        PowerDynamicVarWarmup.EnsureMaterialized(state);
        CardDynamicVarWarmup.EnsureMaterialized(state);

        // Listener enumeration and third-party owner discovery are part of root capture.
        // Take the baseline first so any semantic mutation in those callbacks is rejected by
        // the existing after-capture stamp without paying for another full serialization.
        ContinuationStamp continuationBefore = ContinuationStamp.CaptureLive(state);
        LiveCombatStamp liveBefore = LiveCombatStamp.FromContinuation(continuationBefore);

        Player player = LocalContext.GetMe(state)
            ?? throw new InvalidOperationException("找不到本地玩家。");
        PlayerCombatState playerState = player.PlayerCombatState
            ?? throw new InvalidOperationException("玩家没有战斗状态。");
        AbstractModel[] liveCombatHookListeners = state.IterateHookListeners().ToArray();
        if (liveCombatHookListeners.Any(PredictionModModelSupport.IsBaseLibCardModifier))
        {
            PredictionModModelSupport.RegisterBaseLibCardModifierOwners(
                state.Players
                    .Where(candidate => candidate.PlayerCombatState != null)
                    .SelectMany(candidate => candidate.PlayerCombatState!.AllCards));
        }
        IntentForecast forecast = IntentForecaster.Build(state, SolverWeights.SetupValueHorizonTurns);

        SimulatedCombatState simulatedCombat = new(state, liveCombatHookListeners);
        CombatPredictionSimulator simulator = new(simulatedCombat);
        ContinuationStamp projected = ContinuationStamp.CapturePredicted(
            player,
            simulator,
            playerState.TurnNumber,
            forecast,
            playerState.TurnNumber);
        bool hasUnusedCardReplayAllocator = simulatedCombat.RelicsOf(player)
            .OfType<ThrowingAxe>()
            .Any(relic => !relic.IsMelted && !relic._usedThisCombat);
        bool hasRenewablePotionShapedRock = simulatedCombat.RelicsOf(player)
            .OfType<PetrifiedToad>()
            .Any(relic => !relic.IsMelted);
        PostCombatRelicHealProfile postCombatRelicHeal = CapturePostCombatRelicHeal(
            simulatedCombat.RelicsOf(player));
        PotionRewardOutlook potionRewardOutlook = predictPotionReward
            ? PotionRewardOutlook.Capture(player, state, simulatedCombat.RelicsOf(player))
            : PotionRewardOutlook.None;
        SearchablePotionSlotSnapshot[] searchablePotions = player.PotionSlots
            .Select((potion, slot) => (Potion: potion, Slot: slot))
            .Where(item => item.Potion != null && PotionOnUseSupport.CanSearch(item.Potion))
            .Select(item => new SearchablePotionSlotSnapshot(
                item.Slot,
                item.Potion!.Id.Entry,
                PotionUsePolicy.StrategicHpCost(
                    item.Potion,
                    hasRenewablePotionShapedRock)))
            .ToArray();
        // Card/Power variables were materialized above; potion metadata is also
        // inspected on the main thread. Minion healing deliberately preserves auditing.
        bool hasVisibleHealingSource = playerState.AllCards.Any(card => HasHealingVariables(card.DynamicVars))
            || player.Creature.Powers.Any(power => power is RegenPower
                || HasHealingVariables(power.DynamicVars))
            || player.PotionSlots.Any(potion => potion != null && PotionOnUseSupport.CanSearch(potion)
                && HasHealingVariables(potion.DynamicVars));
        StrategicHpRecoveryBoundAssessment healingBoundAssessment =
            StrategicHpRecoveryBound.Assess(simulator, player);
        if (!string.Equals(
                continuationBefore.StateText,
                projected.StateText,
                StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "Combat root projection differs from the captured live state: " +
                continuationBefore.DescribeFirstDifference(projected));
        }

        ContinuationStamp continuationAfter = ContinuationStamp.CaptureLive(state);
        LiveCombatStamp liveAfter = LiveCombatStamp.FromContinuation(continuationAfter);
        if (!string.Equals(liveBefore.StateText, liveAfter.StateText, StringComparison.Ordinal)
            || !string.Equals(
                continuationBefore.StateText,
                continuationAfter.StateText,
                StringComparison.Ordinal))
        {
            throw new InvalidOperationException("Combat state changed while the root snapshot was being captured.");
        }

        ulong aliveEnemyMask = 0;
        for (int index = 0; index < state.Enemies.Count; index++)
        {
            if (state.Enemies[index].IsAlive)
                aliveEnemyMask |= 1UL << index;
        }
        int cardCount = state.Players
            .Where(candidate => candidate.PlayerCombatState != null)
            .Sum(candidate => candidate.PlayerCombatState!.AllCards.Count());
        IReadOnlySet<string> playerCardIds = playerState.Hand.Cards
            .Concat(playerState.DrawPile.Cards)
            .Concat(playerState.DiscardPile.Cards)
            .Select(card => card.Id.Entry)
            .ToFrozenSet(StringComparer.Ordinal);
        int powerCount = state.Creatures.Sum(creature => creature.Powers.Count);
        CombatHistoryDependencies historyDependencies = CombatHistoryCounterKey.Capture(
                playerState.AllCards.Cast<AbstractModel>().Concat(liveCombatHookListeners)
                    .Concat(player.PotionSlots.OfType<AbstractModel>()),
                simulatedCombat.RootRunModSubscriberCount != 0
                    || simulatedCombat.RootCombatModSubscriberCount != 0
                    || simulatedCombat.RootHasBaseLibCardModifiers
                    || simulatedCombat.AdaptedOnPlay is not null);
        stopwatch.Stop();

        return new CombatRootSnapshot(
            player,
            Array.AsReadOnly(state.Enemies.ToArray()),
            forecast,
            liveBefore,
            continuationBefore,
            simulator,
            state.Players.Count,
            playerState.TurnNumber,
            state.RunState.TotalFloor,
            player.Creature.CurrentHp,
            player.Creature.MaxHp,
            player.PotionSlots.Count,
            Array.AsReadOnly(searchablePotions),
            aliveEnemyMask,
            state.CurrentSide,
            playerState.Phase,
            state.Encounter?.RoomType,
            ActEndingBossPolicy.ResolveHpRelief(state),
            stopwatch.Elapsed.TotalMilliseconds,
            cardCount,
            playerCardIds,
            hasVisibleHealingSource,
            healingBoundAssessment,
            historyDependencies,
            powerCount,
            simulatedCombat.RootHookListenerCount,
            simulatedCombat.RootRunModSubscriberCount,
            simulatedCombat.RootCombatModSubscriberCount,
            simulatedCombat.RootHasBaseLibCardModifiers,
            hasUnusedCardReplayAllocator,
            hasRenewablePotionShapedRock,
            postCombatRelicHeal,
            potionRewardOutlook);
    }

    private static bool HasHealingVariables(DynamicVarSet variables)
        => variables.TryGetValue("Heal", out _)
            || variables.TryGetValue("HealPercent", out _)
            || variables.TryGetValue("RegenPower", out _);

    /// <summary>
    /// Reads how much HP the player's relics will restore once this fight is won.
    /// </summary>
    /// <remarks>
    /// Melted relics are dropped from the hook listener list by the game, so they heal nothing. The heal
    /// amounts come from the live models rather than hard-coded constants so a data-layer rebalance of these
    /// relics is followed without a code change here.
    /// </remarks>
    private static PostCombatRelicHealProfile CapturePostCombatRelicHeal(
        IEnumerable<RelicModel> relics)
    {
        int unconditionalHeal = 0;
        int woundedHeal = 0;
        int woundedHpPercent = 0;
        foreach (RelicModel relic in relics)
        {
            if (relic.IsMelted)
                continue;
            switch (relic)
            {
                case BurningBlood or BlackBlood:
                    unconditionalHeal += relic.DynamicVars.Heal.IntValue;
                    break;
                case MeatOnTheBone:
                    woundedHeal += relic.DynamicVars.Heal.IntValue;
                    woundedHpPercent = Math.Max(
                        woundedHpPercent,
                        relic.DynamicVars[MeatOnTheBone._hpThresholdKey].IntValue);
                    break;
            }
        }
        return new PostCombatRelicHealProfile(unconditionalHeal, woundedHeal, woundedHpPercent);
    }

    public CombatPredictionSimulator ForkSimulator() => _rootSimulator.Fork();
}

narrowScheduleCorrectionSketch.source:
namespace CombatSolver;

internal static partial class CombatSearchCoordinator
{
    private const int MaximumPlanCommitments = 4;
    private const int MaximumDiscoveredPlanCommitments = 18;

    private readonly record struct PlanMemberExecution(
        int MaximumNodes,
        int MaximumMilliseconds,
        bool AggressivePowerCommitment,
        SolverPotionPolicy? PotionPolicyOverride,
        int? MaximumPotionUses,
        bool AllowUnsatisfiedPotion);

    private static SolverResult RunPlanSearchPass(SearchPassContext context, SolverResult baseline)
    {
        if (ReferenceEquals(context.PlanDiscovery.EarlyOpeningPlanProfile, context.Profile)
            || baseline.ResultScope != SolverResultScope.SearchCompletion
            || context.Policy.PotionStrategy.HasForcedDirectives
            || IsProvenZeroDamageRoute(context.Root, context.Policy, baseline)
            || IsCompleteVictory(baseline)
                && baseline.ProjectedBattleHpLost < SolverWeights.PotionMinimumHpSaved * 3)
            return baseline;

        IReadOnlyList<PlanCommitment> plans = DiscoverOpeningPlanCommitments(context);
        context.PlanDiscovery.OpeningPlanCount = plans.Count;
        if (plans.Count == 0)
            return baseline;

        return RunOpeningPlans(context, baseline, plans)!;
    }

    private static SolverResult? TryRunOpeningPlanIncumbent(
        SearchPassContext context, SolverPotionPolicy? potionPolicyOverride)
    {
        SearchPolicySnapshot policy = context.Policy;
        if (!CanRunOpeningPlanIncumbent(context.Root, policy, potionPolicyOverride))
            return null;
        IReadOnlyList<PlanCommitment> plans = DiscoverOpeningPlanCommitments(context);
        if (plans.Count == 0)
            return TryRunNarrowOpeningIncumbent(context, potionPolicyOverride);
        if (plans.Any(plan => plan.UsesPotion))
            return null;
        policy.Diagnostics.Info("[CombatSolver/Test] EARLY_OPENING_PLAN_INCUMBENT start");
        SolverResult? result = RunOpeningPlans(context, null, plans);
        if (result != null && (result.ResultScope != SolverResultScope.SearchCompletion
            || BuildRefinementPrimarySearchIncumbent(context.Root, policy, potionPolicyOverride, result) != null))
        {
            context.PlanDiscovery.OpeningPlanCount = plans.Count;
            context.PlanDiscovery.EarlyOpeningPlanProfile = context.Profile;
            return result;
        }
        return null;
    }

    internal static bool CanRunOpeningPlanIncumbent(CombatRootSnapshot root,
        SearchPolicySnapshot policy, SolverPotionPolicy? potionPolicyOverride)
    {
        // Broad known-source eligibility permits pruning after a victory is found;
        // it does not establish that a speculative plan search is cheap enough to
        // run before the primary member. Keep the existing certified-root schedule.
        if (!root.HasOriginalHealingCertificate
            || !policy.UseBeamWidthPortfolio
            || policy.UseNoveltyPortfolio || policy.IncludeTurnSetup
            || policy.PortfolioExperiment != null || policy.DevelopmentStrategy != null
            || policy.DisableRefinementIncumbentForTesting || policy.DisableOpeningPlanIncumbentForTesting
            || policy.EffectiveHasGrowthTargets
            || policy.RelicTargets.Count != 0 && !CombatBeamSolver.CanUseStrictHpRelicBound(root, policy)
            || policy.PotionStrategy.HasForcedDirectives
            || (potionPolicyOverride ?? policy.PotionPolicy)
                is not (SolverPotionPolicy.Disabled or SolverPotionPolicy.Smart))
            return false;
        return true;
    }

    private static SolverResult? TryRunNarrowOpeningIncumbent(
        SearchPassContext context, SolverPotionPolicy? potionPolicyOverride)
    {
        if (!context.Root.UsesComponentHealingCertificate
            || context.Root.UsesReviewedHealingComponents
            || context.Policy.FixedBudget || context.Profile.BeamWidth < 64
            || context.Profile.SoftTimeBudgetMilliseconds < 30_000)
            return null;
        SearchBudgetWindow window = context.Budget.RequestWindow(context.Profile);
        if (!window.CanStart(7_000))
            return null;
        context.PlanDiscovery.NarrowOpeningIncumbentAttempted = true;
        SolverSearchProfile pilot = window.Limit(context.Profile, 60_000, 20_000, 2_000)
            with { BeamWidth = Math.Max(8, context.Profile.BeamWidth / 16) };
        SolverResult result = new CombatBeamSolver(context.Root, context.DisplayNames,
            context.BattleDamage, context.Policy, context.CancellationToken, context.ProgressCallback,
            pilot, potionPolicyOverride: SolverPotionPolicy.Disabled,
            directSearchPurpose: DirectSearchPurpose.NarrowOpeningIncumbent).Solve();
        bool qualified = BuildRefinementPrimarySearchIncumbent(context.Root, context.Policy,
            potionPolicyOverride, result) != null;
        context.Policy.Diagnostics.Info($"[CombatSolver/Test] NARROW_OPENING_INCUMBENT "
            + $"qualified={qualified} won={IsCompleteVictory(result)} hp_lost={result.ProjectedBattleHpLost} "
            + $"beam={pilot.BeamWidth} expanded={result.ExpandedNodes} elapsed_ms={result.Elapsed.TotalMilliseconds:F1}");
        return qualified ? result : null;
    }

    private static SolverResult? RunOpeningPlans(
        SearchPassContext context, SolverResult? baseline, IReadOnlyList<PlanCommitment> plans)
    {
        SearchPolicySnapshot policy = context.Policy;
        SolverResult? selected = baseline;
        FrontierContinuationScheduler scheduler = new(context);
        int attempted = 0;
        List<PlanCommitment> scheduled = [];
        foreach (int priority in plans.Select(plan => plan.Priority).Distinct()
                     .OrderByDescending(priority => priority))
        {
            PlanCommitment[][] payoffGroups = plans.Where(plan => plan.Priority == priority)
                .GroupBy(plan => plan.Payoff.SourceId)
                .Select(group => group.ToArray())
                .ToArray();
            for (int rank = 0; scheduled.Count < MaximumPlanCommitments; rank++)
            {
                bool found = false;
                foreach (PlanCommitment[] payoffGroup in payoffGroups)
                {
                    if (rank >= payoffGroup.Length)
                        continue;
                    found = true;
                    scheduled.Add(payoffGroup[rank]);
                    if (scheduled.Count == MaximumPlanCommitments)
                        break;
                }
                if (!found)
                    break;
            }
            if (scheduled.Count == MaximumPlanCommitments)
                break;
        }
        foreach (PlanCommitment plan in scheduled)
        {
            if (!TryRunPlanMember(context, scheduler, plan,
                    new PlanMemberExecution(60_000, 20_000,
                        plan.Kind == PlanCommitmentKind.CopyPower,
                        plan.UsesPotion ? SolverPotionPolicy.RequireAtLeastOne
                            : SolverPotionPolicy.Disabled,
                        plan.UsesPotion ? 1 : 0,
                        AllowUnsatisfiedPotion: true),
                    out SolverResult? candidate, selected))
                break;
            attempted++;
            if (candidate == null)
                continue;
            if (candidate.ResultScope != SolverResultScope.SearchCompletion)
                return candidate;
            if (baseline == null && BuildRefinementPrimarySearchIncumbent(context.Root, policy,
                    SolverPotionPolicy.Disabled, candidate) == null)
                continue;
            PopulateSingleSessionTotals(candidate);
            bool improved = selected == null
                || IsBetterPotionPolicyResult(context.Root, policy, candidate, selected);
            if (improved)
                selected = candidate;
            policy.Diagnostics.Info(
                $"[CombatSolver/Test] PLAN_SEARCH_MEMBER kind={plan.Kind} " +
                $"payoff={plan.Payoff.SourceId} potion={plan.UsesPotion} " +
                $"prefix={string.Join(',', plan.Prefix.Select(action =>
                    action.Kind == PlanActionKind.UsePotion
                        ? $"P:{action.PotionId}" + (action.Choice is { Cards.Count: > 0 } potionChoice
                            ? $"[{string.Join('+', potionChoice.Cards.Select(card => card.CardId))}]" : "")
                        : $"C:{action.CardId}" + (action.Choice is { Cards.Count: > 0 } choice
                            ? $"[{string.Join('+', choice.Cards.Select(card => card.CardId))}]" : "")))} " +
                $"opening={string.Join(',', candidate.BestNode.Actions
                    .TakeWhile(action => action.Turn <= context.Root.StartTurnNumber + 1)
                    .Take(16).Select(action => action.Kind == PlanActionKind.UsePotion
                        ? $"P:{action.PotionId}"
                        : action.Kind == PlanActionKind.PlayCard ? $"C:{action.CardId}" : "E"))} " +
                $"won={IsCompleteVictory(candidate)} hp_lost={candidate.ProjectedBattleHpLost} " +
                $"expanded={candidate.ExpandedNodes} selected={improved}");
            if (selected != null && IsProvenZeroDamageRoute(context.Root, policy, selected))
                break;
        }
        policy.Diagnostics.Info(
            $"[CombatSolver/Test] PLAN_SEARCH result candidates={plans.Count} " +
            $"attempted={attempted} selected_hp_lost={selected?.ProjectedBattleHpLost.ToString() ?? "-"}");
        return selected;
    }

    private static SolverResult RunDeferredPowerPlanSearchPass(
        SearchPassContext context, SolverResult baseline)
    {
        if (context.PlanDiscovery.OpeningPlanCount != 0
            || baseline.ResultScope != SolverResultScope.SearchCompletion
            || context.Policy.PotionStrategy.HasForcedDirectives
            || context.Policy.Interaction?.CurrentTakeoverRequest != null
            || baseline.ProjectedBattleHpLost < SolverWeights.PotionMinimumHpSaved * 3
            || !context.Root.PlayerCardIds.Any(PowerCardValuationModels.Registry.ContainsCardId))
            return baseline;

        SearchBudgetWindow scoutWindow = context.Budget.RequestWindow(context.Profile);
        if (!scoutWindow.CanStart(45_000))
            return baseline;

        List<EarlyTurnFrontierCandidate> frontiers = [];
        SolverSearchProfile scoutProfile = scoutWindow.Limit(context.Profile,
            maximumNodes: 25_000, maximumMilliseconds: 8_000,
            reserveMilliseconds: 2_000) with
        {
            StopPortfolioAtHpTarget = false,
        };
        FrontierContinuationScheduler scheduler = new(context);
        scheduler.Dispatch(new ContinuationSearchRequest(context,
            ContinuationPurpose.PlanCommitment, [], scoutProfile,
            SolverPotionPolicy.Disabled, 0, null)
        {
            EarlyTurnScoutDepth = 1,
            EarlyTurnScoutObserver = (turns, candidates) =>
            {
                if (turns == 1)
                    frontiers.AddRange(candidates);
            },
        });

        CombatBeamSolver builder = new(context.Root, context.DisplayNames,
            context.BattleDamage, context.Policy, context.CancellationToken,
            context.ProgressCallback, context.Profile);
        PlanCommitment? plan = null;
        int inspected = 0;
        foreach (EarlyTurnFrontierCandidate frontier in frontiers.Take(8))
        {
            inspected++;
            PlanAction? power = builder.BuildPowerActionsAfterPrefix(frontier.Actions)
                .Select(action => (Action: action,
                    Registered: PowerCardValuationModels.Registry.TryGetCommitmentDescriptor(
                        action.CardId!, out PowerCommitmentDescriptor descriptor),
                    Descriptor: descriptor))
                .Where(item => item.Registered)
                .OrderByDescending(item => item.Descriptor.Priority)
                .Select(item => item.Action)
                .FirstOrDefault();
            if (power == null)
                continue;
            PlanAction[] prefix = [.. frontier.Actions, power];
            plan = new(PlanCommitmentKind.CrossTurnBenefit, prefix,
                context.Root.StartTurnNumber,
                new PlanPayoffEvidence(PlanPayoffEvidenceKind.CardPlayed,
                    power.CardId!, context.Root.StartTurnNumber),
                UsesPotion: false, Priority: 1);
            break;
        }
        if (plan == null)
        {
            context.Policy.Diagnostics.Info(
                $"[CombatSolver/Test] DEFERRED_POWER_PLAN frontiers={inspected} candidate=false");
            return baseline;
        }

        if (!TryRunPlanMember(context, scheduler, plan,
                new PlanMemberExecution(120_000, 60_000,
                    AggressivePowerCommitment: true,
                    PotionPolicyOverride: null,
                    MaximumPotionUses: null,
                    AllowUnsatisfiedPotion: false),
                out SolverResult? memberResult, baseline))
            return baseline;
        SolverResult candidate = memberResult!;
        if (candidate.ResultScope != SolverResultScope.SearchCompletion)
            return candidate;
        PopulateSingleSessionTotals(candidate);
        bool improved = IsBetterPotionPolicyResult(
            context.Root, context.Policy, candidate, baseline);
        context.Policy.Diagnostics.Info(
            $"[CombatSolver/Test] DEFERRED_POWER_PLAN frontiers={inspected} " +
            $"payoff={plan.Payoff.SourceId} won={IsCompleteVictory(candidate)} " +
            $"hp_lost={candidate.ProjectedBattleHpLost} potions={candidate.PotionCount} " +
            $"expanded={candidate.ExpandedNodes} selected={improved}");
        return improved ? candidate : baseline;
    }

    private static bool TryRunPlanMember(
        SearchPassContext context,
        FrontierContinuationScheduler scheduler,
        PlanCommitment plan,
        PlanMemberExecution execution,
        out SolverResult? candidate,
        SolverResult? incumbent = null)
    {
        SearchBudgetWindow window = context.Budget.RequestWindow(context.Profile);
        if (!window.CanStart(7_000))
        {
            candidate = null;
            return false;
        }
        SolverSearchProfile memberProfile = window.Limit(context.Profile,
            maximumNodes: execution.MaximumNodes,
            maximumMilliseconds: execution.MaximumMilliseconds,
            reserveMilliseconds: 2_000) with
        {
            AggressivePowerCommitment = execution.AggressivePowerCommitment,
        };
        ContinuationSearchRequest request = new(context,
            ContinuationPurpose.PlanCommitment, plan.Prefix, memberProfile,
            execution.PotionPolicyOverride, execution.MaximumPotionUses, null)
        {
            Commitment = plan,
            PrimaryIncumbent = incumbent is null ? null : BuildPlanMemberPrimaryIncumbent(
                context.Root, context.Policy, execution.PotionPolicyOverride, incumbent),
        };
        candidate = execution.AllowUnsatisfiedPotion
            ? scheduler.DispatchOptional(request, "PlanCommitment")
            : scheduler.Dispatch(request);
        return true;
    }

    internal static PrimarySearchIncumbent? BuildPlanMemberPrimaryIncumbent(
        CombatRootSnapshot root, SearchPolicySnapshot policy,
        SolverPotionPolicy? potionPolicyOverride, SolverResult incumbent)
        => root.UsesComponentHealingCertificate
            && policy.TheftPolicy != SolverTheftPolicy.PreserveResources
                ? BuildRefinementPrimarySearchIncumbent(root, policy, potionPolicyOverride, incumbent)
                : null;

    private static IReadOnlyList<PlanCommitment> DiscoverOpeningPlanCommitments(
        SearchPassContext context)
    {
        CombatRootSnapshot root = context.Root;
        bool hasPower = root.PlayerCardIds.Any(PowerCardValuationModels.Registry.ContainsCardId);
        CombatBeamSolver builder = new(root, context.DisplayNames, context.BattleDamage,
            context.Policy, context.CancellationToken, context.ProgressCallback, context.Profile,
            potionPolicyOverride: SolverPotionPolicy.RequireAtLeastOne,
            maximumPotionUses: 1);
        DeferredCopyPlanRule[] copyRules = PlanMechanismRegistry.Default.DeferredCopies
            .Where(rule => builder.ContainsChoiceEffectInRoot(rule.Effect))
            .ToArray();
        if (copyRules.Length == 0 && !hasPower)
            return [];

        List<PlanCommitment> plans = [];
        HashSet<string> seen = new(StringComparer.Ordinal);
        Dictionary<(PlanCommitmentKind Kind, string Payoff), int> perPayoff = [];
        void Add(PlanCommitmentKind kind, PlanAction[] prefix, string payoff,
            int priority, int payoffTurnDelay = 1)
        {
            if (plans.Count >= MaximumDiscoveredPlanCommitments
                || perPayoff.GetValueOrDefault((kind, payoff)) >= 2
                || !seen.Add(PowerPrefixKey(prefix)))
                return;
            bool usesPotion = prefix.Any(action => action.Kind == PlanActionKind.UsePotion);
            plans.Add(new(kind, prefix, prefix[0].Turn,
                new PlanPayoffEvidence(PlanPayoffEvidenceKind.CardPlayed,
                    payoff, kind == PlanCommitmentKind.PowerCycle
                        ? prefix[0].Turn : checked(prefix[0].Turn + payoffTurnDelay)),
                usesPotion, priority));
            perPayoff[(kind, payoff)] = perPayoff.GetValueOrDefault((kind, payoff)) + 1;
        }

        int potionOpenings = 0;
        int setupOpenings = 0;
        int copyOptions = 0;
        if (copyRules.Length > 0 && context.Policy.PotionPolicy != SolverPotionPolicy.Disabled)
        {
            foreach (DeferredCopyPlanRule rule in copyRules)
            {
                IReadOnlyList<PlanAction> selectedPotions = builder.BuildOpeningPlanPotionActions(
                    rule.Effect, maximumActions: 6);
                foreach (PlanAction potion in selectedPotions)
                {
                    potionOpenings++;
                    List<PlanAction[]> openings = [[potion]];
                    openings.AddRange(builder.BuildOpeningHandSetupActions([potion],
                            maximumActions: 5,
                            desiredFollowUpEffect: rule.Effect)
                        .Select(setup => new[] { potion, setup }));
                    setupOpenings += openings.Count - 1;
                    foreach (PlanAction[] opening in openings)
                    {
                        foreach (PlanAction copy in builder.BuildOpeningCopyActionsAfterPrefix(
                                     opening, maximumPowerTargets: 3, maximumActions: 8,
                                     desiredEffect: rule.Effect))
                        {
                            copyOptions++;
                            string copiedCardId = copy.Choice!.Cards[0].CardId;
                            bool copiedPower = PowerCardValuationModels.Registry.ContainsCardId(copiedCardId);
                            PlanAction[] copyPrefix = [.. opening, copy];
                            if (copiedPower)
                            {
                                PlanAction? originalPower = builder.BuildPowerActionsAfterPrefix(copyPrefix)
                                    .FirstOrDefault(action => action.CardId == copiedCardId);
                                if (originalPower != null)
                                    Add(PlanCommitmentKind.CopyPower,
                                        [.. copyPrefix, originalPower], copiedCardId,
                                        priority: 4, payoffTurnDelay: rule.PayoffTurnDelay);
                            }
                            Add(copiedPower ? PlanCommitmentKind.CopyPower
                                    : PlanCommitmentKind.CopyCard,
                                copyPrefix, copiedCardId, copiedPower ? 3 : 2,
                                rule.PayoffTurnDelay);
                            if (plans.Count >= MaximumDiscoveredPlanCommitments)
                                break;
                        }
                        if (plans.Count >= MaximumDiscoveredPlanCommitments)
                            break;
                    }
                    if (plans.Count >= MaximumDiscoveredPlanCommitments)
                        break;
                }
                if (plans.Count >= MaximumDiscoveredPlanCommitments)
                    break;
            }
        }
        if (hasPower && plans.Count < MaximumDiscoveredPlanCommitments)
        {
            foreach (PlanAction power in builder.BuildOpeningPowerActions()
                         .Where(action => PowerCardValuationModels.Registry.ContainsCardId(action.CardId!))
                         .Take(2))
            {
                foreach (PlanAction setup in builder.BuildOpeningHandSetupActions([power]).Take(2))
                    Add(PlanCommitmentKind.PowerCycle, [power, setup], power.CardId!, priority: 1);
            }
            foreach (PlanAction setup in builder.BuildOpeningHandSetupActions().Take(2))
            {
                foreach (PlanAction power in builder.BuildPowerActionsAfterPrefix([setup])
                             .Where(action => PowerCardValuationModels.Registry.ContainsCardId(action.CardId!))
                             .Take(1))
                    Add(PlanCommitmentKind.PowerCycle, [setup, power], power.CardId!, priority: 1);
            }
        }
        context.Policy.Diagnostics.Info(
            $"[CombatSolver/Test] PLAN_SEARCH_DISCOVERY count={plans.Count} " +
            $"potion_openings={potionOpenings} setup_openings={setupOpenings} copy_options={copyOptions} " +
            $"copy={plans.Count(plan => plan.Kind is PlanCommitmentKind.CopyPower or PlanCommitmentKind.CopyCard)} " +
            $"power_cycle={plans.Count(plan => plan.Kind == PlanCommitmentKind.PowerCycle)}");
        return plans;
    }
}

